-- Reviewed Korma menu import; no billing, offers, loyalty or customer mutations
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='30s';
CREATE TEMP TABLE korma_before ON COMMIT DROP AS SELECT jsonb_build_object('subscriptions',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.subscriptions t ),'loyalty_cards',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.loyalty_cards t ),'cafe_loyalty_programs',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_loyalty_programs t ),'cafe_loyalty_experience',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_loyalty_experience t ),'offers',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.offers t ),'cafes',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.cafes t ),'menu_products',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.menu_products t WHERE cafe_id<>'540dd021-399e-49b0-b6bd-33fb66abfb3b'),'menu_categories',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.menu_categories t WHERE cafe_id<>'540dd021-399e-49b0-b6bd-33fb66abfb3b'),'cafe_custom_identity',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_custom_identity t WHERE cafe_id<>'540dd021-399e-49b0-b6bd-33fb66abfb3b'),'cafe_settings',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_settings t WHERE cafe_id<>'540dd021-399e-49b0-b6bd-33fb66abfb3b'),'brand_feature_overrides',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.brand_feature_overrides t )) snapshot;
DO $identity$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.cafes WHERE id='540dd021-399e-49b0-b6bd-33fb66abfb3b' AND slug='brand-b042ca7f1a93' AND status='active' AND deleted_at IS NULL) THEN RAISE EXCEPTION 'Korma brand identity changed';END IF;END $identity$;
CREATE TEMP TABLE korma_expected_categories ON COMMIT DROP AS SELECT * FROM public.menu_categories WITH NO DATA;
DO $catalog$ BEGIN IF EXISTS(SELECT 1 FROM public.menu_categories WHERE cafe_id='540dd021-399e-49b0-b6bd-33fb66abfb3b') AND (EXISTS(SELECT id,cafe_id,branch_id,name,description,sort_order,visible FROM public.menu_categories WHERE cafe_id='540dd021-399e-49b0-b6bd-33fb66abfb3b' EXCEPT SELECT id,cafe_id,branch_id,name,description,sort_order,visible FROM korma_expected_categories) OR EXISTS(SELECT id,cafe_id,branch_id,name,description,sort_order,visible FROM korma_expected_categories EXCEPT SELECT id,cafe_id,branch_id,name,description,sort_order,visible FROM public.menu_categories WHERE cafe_id='540dd021-399e-49b0-b6bd-33fb66abfb3b')) THEN RAISE EXCEPTION 'Existing categories differ; preserve owner changes';END IF;END $catalog$;
CREATE TEMP TABLE korma_expected_products ON COMMIT DROP AS SELECT * FROM public.menu_products WITH NO DATA;
دايت: 3 ر.س
ليمون: 3 ر.س
برتقال: 3 ر.س',3,'{3}',NULL,34,true,'product','540dd021-399e-49b0-b6bd-33fb66abfb3b/ffbda459-ef15-449e-8e3a-c4dd9f955124/korma-20261103-302496d27e5a4010.webp','{}','{"options":[{"id":"variant-1","label":"كينزا","price":3,"available":true},{"id":"variant-2","label":"دايت","price":3,"available":true},{"id":"variant-3","label":"ليمون","price":3,"available":true},{"id":"variant-4","label":"برتقال","price":3,"available":true}]}'::jsonb);
DO $catalog$ BEGIN IF EXISTS(SELECT 1 FROM public.menu_products WHERE cafe_id='540dd021-399e-49b0-b6bd-33fb66abfb3b') AND (EXISTS(SELECT id,cafe_id,branch_id,category_id,name,description,price,price_options,calories,sort_order,available,catalog_kind,image_storage_path,gallery_storage_paths,commerce_details FROM public.menu_products WHERE cafe_id='540dd021-399e-49b0-b6bd-33fb66abfb3b' EXCEPT SELECT id,cafe_id,branch_id,category_id,name,description,price,price_options,calories,sort_order,available,catalog_kind,image_storage_path,gallery_storage_paths,commerce_details FROM korma_expected_products) OR EXISTS(SELECT id,cafe_id,branch_id,category_id,name,description,price,price_options,calories,sort_order,available,catalog_kind,image_storage_path,gallery_storage_paths,commerce_details FROM korma_expected_products EXCEPT SELECT id,cafe_id,branch_id,category_id,name,description,price,price_options,calories,sort_order,available,catalog_kind,image_storage_path,gallery_storage_paths,commerce_details FROM public.menu_products WHERE cafe_id='540dd021-399e-49b0-b6bd-33fb66abfb3b')) THEN RAISE EXCEPTION 'Existing products differ; preserve owner changes';END IF;END $catalog$;
DO $logo$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.cafe_settings WHERE cafe_id='540dd021-399e-49b0-b6bd-33fb66abfb3b') THEN RAISE EXCEPTION 'Korma settings missing';END IF;IF EXISTS(SELECT 1 FROM public.cafe_settings WHERE cafe_id='540dd021-399e-49b0-b6bd-33fb66abfb3b' AND ((logo_storage_path IS NOT NULL AND logo_storage_path IS DISTINCT FROM '540dd021-399e-49b0-b6bd-33fb66abfb3b/identity/korma-20261103-f015b2c0a8d655ae.webp') OR logo_url IS NOT NULL)) OR EXISTS(SELECT 1 FROM public.cafe_custom_identity WHERE cafe_id='540dd021-399e-49b0-b6bd-33fb66abfb3b' AND (logo_storage_path IS DISTINCT FROM '540dd021-399e-49b0-b6bd-33fb66abfb3b/identity/korma-20261103-f015b2c0a8d655ae.webp' OR logo_url IS NOT NULL OR palette IS DISTINCT FROM '{"primary":"#123D32","secondary":"#FFF6E6","accent":"#F49B49","background":"#123D32","text":"#FFF6E6"}'::jsonb)) THEN RAISE EXCEPTION 'Existing Korma identity differs; preserve owner changes';END IF;END $logo$;
UPDATE public.cafe_settings SET logo_storage_path='540dd021-399e-49b0-b6bd-33fb66abfb3b/identity/korma-20261103-f015b2c0a8d655ae.webp',updated_at=now() WHERE cafe_id='540dd021-399e-49b0-b6bd-33fb66abfb3b' AND logo_storage_path IS DISTINCT FROM '540dd021-399e-49b0-b6bd-33fb66abfb3b/identity/korma-20261103-f015b2c0a8d655ae.webp';
DO $verify$ DECLARE actual jsonb;BEGIN SELECT jsonb_build_object('subscriptions',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.subscriptions t ),'loyalty_cards',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.loyalty_cards t ),'cafe_loyalty_programs',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_loyalty_programs t ),'cafe_loyalty_experience',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_loyalty_experience t ),'offers',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.offers t ),'cafes',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.cafes t ),'menu_products',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.menu_products t WHERE cafe_id<>'540dd021-399e-49b0-b6bd-33fb66abfb3b'),'menu_categories',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.menu_categories t WHERE cafe_id<>'540dd021-399e-49b0-b6bd-33fb66abfb3b'),'cafe_custom_identity',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_custom_identity t WHERE cafe_id<>'540dd021-399e-49b0-b6bd-33fb66abfb3b'),'cafe_settings',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_settings t WHERE cafe_id<>'540dd021-399e-49b0-b6bd-33fb66abfb3b'),'brand_feature_overrides',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.brand_feature_overrides t )) INTO actual;IF actual IS DISTINCT FROM(SELECT snapshot FROM korma_before) THEN RAISE EXCEPTION 'Protected brands, loyalty, billing or customer data changed';END IF;IF(SELECT count(*) FROM public.menu_products WHERE cafe_id='540dd021-399e-49b0-b6bd-33fb66abfb3b' AND available AND price>0)<>36 OR(SELECT count(*) FROM public.menu_categories WHERE cafe_id='540dd021-399e-49b0-b6bd-33fb66abfb3b')<>10 OR(SELECT sum(coalesce(jsonb_array_length(commerce_details->'options'),0)) FROM public.menu_products WHERE cafe_id='540dd021-399e-49b0-b6bd-33fb66abfb3b')<>4 THEN RAISE EXCEPTION 'Korma count, prices or media mismatch';END IF;END $verify$;
COMMIT;
